#!/usr/bin/env python3
# Autonomously generated by an AI agent.
"""Compile or install Mixxx with Beat This! in user directories on Linux."""

import argparse
import hashlib
import os
from pathlib import Path
import platform
import shlex
import shutil
import subprocess
import sys
import tempfile
import urllib.request

REPOSITORY = "https://github.com/gabba43/mixxx.git"
REF = "feat/beat-this-variable-tempo"
MODEL_URL = (
    "https://cloud.cp.jku.at/public.php/dav/files/7ik4RrBKTS273gp/final0.ckpt"
)
MODEL_SHA256 = (
    "8c328b45f59d8dd3dff219253ff6a8d6482be57d0133a29140e2febbf8eb8331"
)
SOURCE_FILES = (
    "CMakeLists.txt",
    "src/analyzer/plugins/analyzerbeatthis.cpp",
    "res/analysis/beat_this_worker.py",
    "tools/requirements-beat-this.txt",
)


def run(command, **kwargs):
    command = [str(arg) for arg in command]
    print("+ " + shlex.join(command), flush=True)
    return subprocess.run(command, check=True, **kwargs)


def absolute(value):
    path = Path(value).expanduser().absolute()
    if any(char in str(path) for char in "\r\n\x00"):
        raise ValueError("Paths must not contain newlines or NUL bytes")
    return path


def is_source(path):
    return all((path / name).is_file() for name in SOURCE_FILES)


def source_directory(explicit, destination, repository, ref):
    script = Path(__file__).resolve()
    candidates = (script.parent, script.parents[1], Path.cwd())
    source = (
        absolute(explicit)
        if explicit
        else next(
            (candidate for candidate in candidates if is_source(candidate)),
            destination,
        )
    )
    if source.exists():
        if not is_source(source):
            raise ValueError(
                f"Not a Mixxx/Beat This! source directory: {source}"
            )
        print(f"Using existing sources unchanged: {source}", flush=True)
    else:
        source.parent.mkdir(parents=True, exist_ok=True)
        run(
            [
                "git",
                "clone",
                "--single-branch",
                "--branch",
                ref,
                "--",
                repository,
                source,
            ]
        )
        if not is_source(source):
            raise ValueError(
                f"The selected Git ref does not include Beat This!: {ref}"
            )
    return source


def dependency_help():
    distribution = "unknown distribution"
    release = Path("/etc/os-release")
    if release.is_file():
        for line in release.read_text().splitlines():
            if line.startswith("PRETTY_NAME="):
                distribution = line.split("=", 1)[1].strip('"')
    print(
        f"Detected: {distribution}\n"
        "Requires C++20, CMake >= 3.22, pkg-config, Make or Ninja,\n"
        "Python 3.10–3.12 with venv/pip, and Mixxx's native libraries:\n"
        "Qt 6 with private headers, audio/codecs, USB/MIDI, etc.\n"
        "Debian/Ubuntu: see packaging/debian/control.in for native packages.\n"
        "Fedora: dnf builddep mixxx; Arch: the Mixxx PKGBUILD makedepends;\n"
        "openSUSE: zypper source-install --build-deps-only mixxx.\n"
        "Distro packages can target an older Qt/version: also check\n"
        "LINUX_INSTALL.md and CMake errors for missing dependencies.\n"
        "This installer executes no system package manager or sudo command.\n"
        "Guide: https://github.com/mixxxdj/mixxx/wiki/Compiling-On-Linux\n"
        "The pinned PyTorch runtime needs glibc Linux on x86_64 or aarch64;\n"
        "musl-only distributions (e.g. native Alpine) are not supported."
    )


def choose_python(explicit):
    candidates = (
        [explicit]
        if explicit
        else [sys.executable, "python3.12", "python3.11", "python3.10"]
    )
    for candidate in candidates:
        executable = shutil.which(str(candidate))
        if executable:
            probe = subprocess.run(
                [
                    executable,
                    "-c",
                    "import sys, venv, ensurepip, platform; "
                    "assert platform.python_implementation() == 'CPython'; "
                    "print('%s.%s' % sys.version_info[:2])",
                ],
                capture_output=True,
                text=True,
            )
            if probe.returncode == 0 and probe.stdout.strip() in {
                "3.10",
                "3.11",
                "3.12",
            }:
                return absolute(executable)
    raise ValueError(
        "Install Python 3.10–3.12 with venv/ensurepip; select with --python"
    )


def configure_build(source, build, prefix, extra):
    build.mkdir(parents=True, exist_ok=True)
    command = ["cmake", "-S", source, "-B", build]
    if not (build / "CMakeCache.txt").exists():
        command += [
            "-DCMAKE_BUILD_TYPE=Release",
            "-DBUILD_TESTING=OFF",
            "-DBUILD_BENCH=OFF",
        ]
        if shutil.which("ninja"):
            command += ["-G", "Ninja"]
    command += extra
    command += [
        f"-DCMAKE_INSTALL_PREFIX={prefix}",
        "-DCMAKE_INSTALL_BINDIR=bin",
        "-DCMAKE_INSTALL_DATADIR=share",
        "-DCMAKE_INSTALL_DATAROOTDIR=share",
        "-DCMAKE_INSTALL_LIBDIR=lib",
        "-DCMAKE_INSTALL_DOCDIR=share/doc/mixxx",
    ]
    run(command)


def install_runtime(python, source, prefix, architecture):
    environment = prefix / "venv"
    interpreter = environment / "bin/python"
    if not interpreter.exists():
        run([python, "-m", "venv", environment])
    else:
        choose_python(interpreter)
    run(
        [
            interpreter,
            "-c",
            "import sys; assert sys.prefix != sys.base_prefix, "
            "'Expected an isolated venv'",
        ]
    )
    run([interpreter, "-m", "pip", "install", "--upgrade", "pip"])
    command = [interpreter, "-m", "pip", "install", "--only-binary=:all:"]
    if architecture in {"x86_64", "amd64"}:
        command += [
            "--index-url",
            "https://download.pytorch.org/whl/cpu",
            "torch==2.5.1+cpu",
            "torchaudio==2.5.1+cpu",
        ]
    else:
        command += [
            "--index-url",
            "https://pypi.org/simple",
            "torch==2.5.1",
            "torchaudio==2.5.1",
        ]
    run(command)
    run(
        [
            interpreter,
            "-m",
            "pip",
            "install",
            "-r",
            source / "tools/requirements-beat-this.txt",
        ]
    )
    run([interpreter, "-m", "pip", "check"])
    run(
        [
            interpreter,
            "-c",
            "import beat_this, torch, torchaudio, soxr; "
            "print('Beat This! runtime ready:', torch.__version__)",
        ]
    )
    return interpreter


def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def install_model(destination, existing=None):
    destination.parent.mkdir(parents=True, exist_ok=True)
    if destination.exists():
        if sha256(destination) != MODEL_SHA256:
            raise ValueError(
                f"Checkpoint checksum mismatch; replace {destination}"
            )
        print(f"Reusing verified checkpoint: {destination}", flush=True)
        return
    with tempfile.NamedTemporaryFile(
        dir=destination.parent, delete=False
    ) as output:
        temporary = Path(output.name)
        try:
            if existing:
                with absolute(existing).open("rb") as stream:
                    shutil.copyfileobj(stream, output)
            else:
                print(
                    f"Downloading final0 checkpoint (~78 MiB): {MODEL_URL}",
                    flush=True,
                )
                with urllib.request.urlopen(MODEL_URL, timeout=120) as stream:
                    shutil.copyfileobj(stream, output)
            output.flush()
            if sha256(temporary) != MODEL_SHA256:
                raise ValueError(
                    "Checkpoint does not match the official final0 SHA-256"
                )
            output.close()
            temporary.replace(destination)
        finally:
            temporary.unlink(missing_ok=True)


def write_atomic(path, content, mode=0o600):
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        mode="w", encoding="utf-8", dir=path.parent, delete=False
    ) as stream:
        temporary = Path(stream.name)
        try:
            stream.write(content)
            stream.close()
            temporary.chmod(mode)
            temporary.replace(path)
        finally:
            temporary.unlink(missing_ok=True)


def configure_profile(profile, interpreter, model):
    config = profile / "mixxx.cfg"
    old = config.read_text(encoding="utf-8") if config.exists() else ""
    settings = {}
    section = None
    for line in old.splitlines():
        line = line.strip()
        if line.startswith("[") and line.endswith("]"):
            section = line
        elif section and line:
            pair = line.split(maxsplit=1)
            settings.setdefault(section, {})[pair[0]] = (
                pair[1] if len(pair) == 2 else ""
            )
    bpm = settings.setdefault("[BPM]", {})
    bpm.update(
        BeatThisPython=str(interpreter),
        BeatThisModel=str(model),
        BeatThisModelSha256=MODEL_SHA256,
    )
    if "tempo_mode" not in bpm:
        legacy = bpm.get("BeatDetectionFixedTempoAssumption")
        bpm["tempo_mode"] = (
            "0" if legacy is None else ("1" if legacy == "1" else "2")
        )
    bpm.setdefault("BPMDetectionEnabled", "1")
    settings.setdefault("[Vamp]", {})["AnalyserBeatPluginID"] = "beat-this:1"
    content = "".join(
        "\n"
        + group
        + "\n"
        + "".join(f"{key} {value}\n" for key, value in values.items())
        for group, values in settings.items()
    )
    if content != old:
        if config.exists():
            shutil.copy2(config, profile / "mixxx.cfg.before-beat-this")
        write_atomic(config, content)


def desktop_quote(value):
    value = (
        str(value)
        .replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("`", "\\`")
        .replace("$", "\\$")
    )
    return '"' + value.replace("\\", "\\\\").replace("%", "%%") + '"'


def install_launchers(prefix, profile, bin_dir, data_home):
    launcher = prefix / "bin/mixxx-beat-this"
    command = [
        prefix / "bin/mixxx",
        "--resource-path",
        prefix / "share/mixxx",
        "--settings-path",
        profile,
    ]
    write_atomic(
        launcher,
        "#!/bin/sh\n# Autonomously generated by an AI agent.\nexec "
        + shlex.join([str(arg) for arg in command])
        + ' "$@"\n'
        + "# End of autonomously generated text.\n",
        0o755,
    )
    bin_dir.mkdir(parents=True, exist_ok=True)
    link = bin_dir / "mixxx-beat-this"
    if link.resolve() != launcher.resolve():
        if link.exists() or link.is_symlink():
            raise ValueError(
                f"Refusing to replace an unrelated starter: {link}"
            )
        else:
            link.symlink_to(launcher)
    icon = str(prefix / "share/icons/hicolor/scalable/apps/mixxx.svg").replace(
        "\\", "\\\\"
    )
    write_atomic(
        data_home / "applications/org.mixxx.Mixxx.BeatThis.desktop",
        "# Autonomously generated by an AI agent.\n"
        "[Desktop Entry]\nType=Application\nName=Mixxx (Beat This!)\n"
        "Comment=Mixxx with local Beat This! analysis\n"
        f"Exec={desktop_quote(launcher)} %F\nIcon={icon}\n"
        "Terminal=false\nCategories=AudioVideo;Audio;\n"
        "# End of autonomously generated text.\n",
        0o644,
    )
    return link


def choose_mode(mode):
    if mode:
        return mode
    if not sys.stdin.isatty():
        raise ValueError(
            "Select --mode build or --mode install for non-interactive use"
        )
    while True:
        answer = (
            input(
                "Nur kompilieren (Terminal/eigener Shortcut) [b] oder "
                "mit Starter im Benutzerverzeichnis installieren [i]? "
            )
            .strip()
            .lower()
        )
        if answer in {"b", "build"}:
            return "build"
        if answer in {"i", "install"}:
            return "install"


def main(argv=None):
    home = Path.home()
    data_home = absolute(
        os.environ.get("XDG_DATA_HOME", home / ".local/share")
    )
    cache_home = absolute(os.environ.get("XDG_CACHE_HOME", home / ".cache"))
    config_home = absolute(os.environ.get("XDG_CONFIG_HOME", home / ".config"))
    parser = argparse.ArgumentParser(
        description=__doc__,
        epilog="Close this Mixxx profile before installing/updating. "
        "No sudo or system package installation.",
    )
    parser.add_argument(
        "--mode",
        choices=("build", "install"),
        help="Compile, or install with a starter; asked when omitted",
    )
    parser.add_argument(
        "--prefix", type=absolute, default=home / ".local/opt/mixxx-beat-this"
    )
    parser.add_argument(
        "--source-dir",
        help="Existing sources, or a new directory to clone into",
    )
    parser.add_argument(
        "--build-dir",
        type=absolute,
        default=cache_home / "mixxx-beat-this/build",
    )
    parser.add_argument(
        "--profile", type=absolute, default=config_home / "mixxx-beat-this"
    )
    parser.add_argument(
        "--bin-dir", type=absolute, default=home / ".local/bin"
    )
    parser.add_argument(
        "--python",
        help="Python 3.10–3.12 interpreter for the isolated runtime",
    )
    parser.add_argument(
        "--runtime-dir",
        type=absolute,
        help="Python/model directory (default: install prefix, "
        "or XDG data directory in build mode)",
    )
    parser.add_argument(
        "--jobs", type=int, default=min(os.cpu_count() or 1, 4)
    )
    parser.add_argument("--repository", default=REPOSITORY)
    parser.add_argument(
        "--ref",
        default=REF,
        help="Branch/tag for NEW clones; existing sources remain unchanged",
    )
    parser.add_argument(
        "--model-file",
        type=absolute,
        help="Copy an already downloaded official final0 checkpoint",
    )
    parser.add_argument(
        "--cmake-arg",
        action="append",
        default=[],
        help="Extra CMake argument; use --cmake-arg=-DNAME=VALUE",
    )
    parser.add_argument(
        "--print-deps",
        action="store_true",
        help="Show native prerequisites and exit",
    )
    args = parser.parse_args(argv)
    if args.print_deps:
        dependency_help()
        return
    mode = choose_mode(args.mode)
    if sys.platform != "linux" or os.geteuid() == 0:
        parser.error("Run this installer as a regular user on Linux")
    architecture = platform.machine().lower()
    if (
        architecture not in {"x86_64", "amd64", "aarch64", "arm64"}
        or platform.libc_ver()[0] != "glibc"
    ):
        parser.error(
            "Pinned PyTorch wheels require glibc Linux on x86_64 or aarch64"
        )
    if args.jobs < 1:
        parser.error("--jobs must be at least 1")
    for tool in ("cmake", "pkg-config"):
        if not shutil.which(tool):
            raise ValueError(f"Missing build tool: {tool}; see --print-deps")
    python = choose_python(args.python)
    source = source_directory(
        args.source_dir,
        data_home / "mixxx-beat-this/source",
        args.repository,
        args.ref,
    )
    configure_build(source, args.build_dir, args.prefix, args.cmake_arg)
    run(["cmake", "--build", args.build_dir, "--parallel", args.jobs])
    if mode == "install":
        run(["cmake", "--install", args.build_dir, "--prefix", args.prefix])
    runtime = args.runtime_dir or (
        args.prefix
        if mode == "install"
        else data_home / "mixxx-beat-this/runtime"
    )
    interpreter = install_runtime(python, source, runtime, architecture)
    model = runtime / "models/final0.ckpt"
    install_model(model, args.model_file)
    configure_profile(args.profile, interpreter, model)
    if mode == "install":
        launcher = install_launchers(
            args.prefix, args.profile, args.bin_dir, data_home
        )
        print(
            f"\nInstalled. Start: {shlex.quote(str(launcher))}\n"
            "Desktop entry: Mixxx (Beat This!)"
        )
    else:
        command = [
            args.build_dir / "mixxx",
            "--resource-path",
            source / "res",
            "--settings-path",
            args.profile,
        ]
        print(
            "\nCompiled. Start in a terminal or use in your own shortcut:\n"
            + shlex.join([str(arg) for arg in command])
        )
    print(
        f"Profile: {args.profile}\n"
        "Beat This! is selected; a new profile uses Auto tempo mode.\n"
        "Sources are reused. Pull/select the desired Git revision yourself\n"
        "before rerunning this script."
    )


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, subprocess.CalledProcessError) as error:
        print(
            f"Installation failed: {error}\n"
            "Run with --print-deps for prerequisites.",
            file=sys.stderr,
        )
        sys.exit(1)
    except KeyboardInterrupt:
        print(
            "Installation interrupted; rerun to resume the build/download.",
            file=sys.stderr,
        )
        sys.exit(130)
# End of autonomously generated text.
